if ChoiceVal bsr 8 =:= 0 ->
[<<0:2>>,
align,
ChoiceVal];
true ->
exit({error,{asn1,{illegal_integer,ChoiceVal}}})
end;
ChoiceTag =:= 'mqtt-sn' ->
if ChoiceVal bsr 8 =:= 0 ->
[<<1:2>>,
align,
ChoiceVal];
true ->
exit({error,{asn1,{illegal_integer,ChoiceVal}}})
end;
ChoiceTag =:= coap ->
if ChoiceVal bsr 8 =:= 0 ->
[<<2:2>>,
align,
ChoiceVal];
true ->
exit({error,{asn1,{illegal_integer,ChoiceVal}}})
end
end.


dec_ProtoVer(Bytes) ->
{Choice,Bytes1} = 
begin
<<V1@V0:2/unsigned-unit:1,V1@Buf1/bitstring>> = Bytes,
{V1@V0,V1@Buf1}
end,
case Choice of
0 ->
{Val,NewBytes} = begin
begin
V2@Pad2 = bit_size(Bytes1) band 7,
<<_:V2@Pad2,V2@V0:1/unsigned-unit:8,V2@Buf1/bitstring>> = Bytes1,
{V2@V0,V2@Buf1}
end
end,
{{mqtt,Val},NewBytes};
1 ->
{Val,NewBytes} = begin
begin
V3@Pad2 = bit_size(Bytes1) band 7,
<<_:V3@Pad2,V3@V0:1/unsigned-unit:8,V3@Buf1/bitstring>> = Bytes1,
{V3@V0,V3@Buf1}
end
end,
{{'mqtt-sn',Val},NewBytes};
2 ->
{Val,NewBytes} = begin
begin
V4@Pad2 = bit_size(Bytes1) band 7,
<<_:V4@Pad2,V4@V0:1/unsigned-unit:8,V4@Buf1/bitstring>> = Bytes1,
{V4@V0,V4@Buf1}
end
end,
{{coap,Val},NewBytes}
end.
enc_StdHeaders(Val) ->
[begin
Enc1@element = element(2, Val),
Enc2@element = element(3, Val),
if Enc1@element =:= asn1_NOVALUE ->
if Enc2@element =:= asn1_NOVALUE ->
<<0:1,0:1>>;
true ->
<<0:1,1:1>>
end;
true ->
if Enc2@element =:= asn1_NOVALUE ->
<<1:1,0:1>>;
true ->
<<1:1,1:1>>
end
end
end,
begin
Enc3@element = element(4, Val),
Enc4@element = element(5, Val),
if Enc3@element =:= asn1_NOVALUE ->
if Enc4@element =:= asn1_NOVALUE ->
<<0:1,0:1>>;
true ->
<<0:1,1:1>>
end;
true ->
if Enc4@element =:= asn1_NOVALUE ->
<<1:1,0:1>>;
true ->
<<1:1,1:1>>
end
end
end,
begin
%% attribute protoVer(1) with type ProtoVer
Enc5@element = element(2, Val),
if Enc5@element =:= asn1_NOVALUE ->
[];
true ->
enc_ProtoVer(Enc5@element)
end
end,
begin
%% attribute peerhost(2) with type OCTET STRING
Enc7@element = element(3, Val),
if Enc7@element =:= asn1_NOVALUE ->
[];
true ->
begin
Enc8@len = byte_size(Enc7@element),
Enc8@len@sub = Enc8@len - 4,
if 0 =< Enc8@len@sub, Enc8@len@sub < 13 ->
[<<Enc8@len@sub:4>>,
align|Enc7@element]
end
end
end
end,
begin
%% attribute peername(3) with type OCTET STRING
Enc10@element = element(4, Val),
if Enc10@element =:= asn1_NOVALUE ->
[];
true ->
begin
Enc11@len = byte_size(Enc10@element),
Enc11@len@sub = Enc11@len - 6,
if 0 =< Enc11@len@sub, Enc11@len@sub < 13 ->
[<<Enc11@len@sub:4>>,
align|Enc10@element]
end
end
end
end|begin
%% attribute username(4) with type OCTET STRING
Enc13@element = element(5, Val),
if Enc13@element =:= asn1_NOVALUE ->
[];
true ->
begin
Enc14@len = byte_size(Enc13@element),
if Enc14@len < 128 ->
[align,
Enc14@len|Enc13@element];
Enc14@len < 16384 ->
[align,
<<2:2,Enc14@len:14>>|Enc13@element];
true ->
[align|encode_fragmented(Enc13@element, 8)]
end
end
end
end].


dec_StdHeaders(Bytes) ->
{Opt,Bytes1} = begin
<<V1@V0:4,V1@Buf1/bitstring>> = Bytes,
{V1@V0,V1@Buf1}
end,

%% attribute protoVer(1) with type ProtoVer
{Term1,Bytes2} = case (Opt bsr 3) band 1 of
1 ->
dec_ProtoVer(Bytes1);
0 ->
{asn1_NOVALUE,Bytes1}
end,

%% attribute peerhost(2) with type OCTET STRING
{Term2,Bytes3} = case (Opt bsr 2) band 1 of
1 ->
begin
<<V2@V0:4/unsigned-unit:1,V2@Buf1/bitstring>> = Bytes2,
V2@Add2 = V2@V0 + 4,
V2@Pad5 = bit_size(V2@Buf1) band 7,
<<_:V2@Pad5,V2@V3:V2@Add2/binary-unit:8,V2@Buf4/bitstring>> = V2@Buf1,
V2@Conv7 = binary:copy(V2@V3),
{V2@Conv7,V2@Buf4}
end;
0 ->
{asn1_NOVALUE,Bytes2}
end,

%% attribute peername(3) with type OCTET STRING
{Term3,Bytes4} = case (Opt bsr 1) band 1 of
1 ->
begin
<<V3@V0:4/unsigned-unit:1,V3@Buf1/bitstring>> = Bytes3,
V3@Add2 = V3@V0 + 6,
V3@Pad5 = bit_size(V3@Buf1) band 7,
<<_:V3@Pad5,V3@V3:V3@Add2/binary-unit:8,V3@Buf4/bitstring>> = V3@Buf1,
V3@Conv7 = binary:copy(V3@V3),
{V3@Conv7,V3@Buf4}
end;
0 ->
{asn1_NOVALUE,Bytes3}
end,

%% attribute username(4) with type OCTET STRING
{Term4,Bytes5} = case Opt band 1 of
1 ->
begin
V4@Pad3 = bit_size(Bytes4) band 7,
{V4@V0,V4@Buf1} = case Bytes4 of
<<_:V4@Pad3,0:1,V4@V5:7,V4@V7:V4@V5/binary-unit:8,V4@Buf8/bitstring>> ->
{V4@V7,V4@Buf8};
<<_:V4@Pad3,1:1,0:1,V4@V6:14,V4@V8:V4@V6/binary-unit:8,V4@Buf9/bitstring>> ->
{V4@V8,V4@Buf9};
<<_:V4@Pad3,1:1,1:1,V4@V6:6,V4@Buf7/bitstring>> ->
{V4@V8,V4@Buf9}  = decode_fragmented(V4@V6, V4@Buf7, 8),
{V4@V8,V4@Buf9}
end,
V4@Conv10 = binary:copy(V4@V0),
{V4@Conv10,V4@Buf1}
end;
0 ->
{asn1_NOVALUE,Bytes4}
end,
Res1 = {'StdHeaders',Term1,Term2,Term3,Term4},
{Res1,Bytes5}.

enc_From(Val) ->
{ChoiceTag,ChoiceVal} = Val,
if ChoiceTag =:= atom ->
begin
Enc2@bin = iolist_to_binary(ChoiceVal),
Enc2@len = byte_size(Enc2@bin),
if Enc2@len < 128 ->
[<<0:1>>,
align,
Enc2@len|Enc2@bin];
Enc2@len < 16384 ->
[<<0:1>>,
align,
<<2:2,Enc2@len:14>>|Enc2@bin];
true ->
[<<0:1>>,
align|encode_fragmented(Enc2@bin, 8)]
end
end;
ChoiceTag =:= binary ->
begin
Enc4@len = byte_size(ChoiceVal),
if Enc4@len < 128 ->
[<<1:1>>,
align,
Enc4@len|ChoiceVal];
Enc4@len < 16384 ->
[<<1:1>>,
align,
<<2:2,Enc4@len:14>>|ChoiceVal];
true ->
[<<1:1>>,
align|encode_fragmented(ChoiceVal, 8)]
end
end
end.


dec_From(Bytes) ->
{Choice,Bytes1} = 
begin
<<V1@V0:1/unsigned-unit:1,V1@Buf1/bitstring>> = Bytes,
{V1@V0,V1@Buf1}
end,
case Choice of
0 ->
{Val,NewBytes} = begin
begin
V2@Pad3 = bit_size(Bytes1) band 7,
{V2@V0,V2@Buf1} = case Bytes1 of
<<_:V2@Pad3,0:1,V2@V5:7,V2@Buf6/bitstring>> ->
{V2@V5,V2@Buf6};
<<_:V2@Pad3,1:1,0:1,V2@V6:14,V2@Buf7/bitstring>> ->
{V2@V6,V2@Buf7};
<<_:V2@Pad3,1:1,1:1,V2@V6:6,V2@Buf7/bitstring>> ->
V2@Mul8 = V2@V6 * 16384,
{V2@Mul8,V2@Buf7}
end,
<<V2@V9:V2@V0/binary-unit:8,V2@Buf10/bitstring>> = V2@Buf1,
{V2@V9,V2@Buf10}
end
end,
{{atom,Val},NewBytes};
1 ->
{Val,NewBytes} = begin
begin
V3@Pad3 = bit_size(Bytes1) band 7,
{V3@V0,V3@Buf1} = case Bytes1 of
<<_:V3@Pad3,0:1,V3@V5:7,V3@V7:V3@V5/binary-unit:8,V3@Buf8/bitstring>> ->
{V3@V7,V3@Buf8};
<<_:V3@Pad3,1:1,0:1,V3@V6:14,V3@V8:V3@V6/binary-unit:8,V3@Buf9/bitstring>> ->
{V3@V8,V3@Buf9};
<<_:V3@Pad3,1:1,1:1,V3@V6:6,V3@Buf7/bitstring>> ->
{V3@V8,V3@Buf9}  = decode_fragmented(V3@V6, V3@Buf7, 8),
{V3@V8,V3@Buf9}
end,
V3@Conv10 = binary:copy(V3@V0),
{V3@Conv10,V3@Buf1}
end
end,
{{binary,Val},NewBytes}
end.
enc_DurableMessage(Val) ->
[begin
Enc1@element = element(13, Val),
if Enc1@element =:= asn1_NOVALUE ->
<<0:1>>;
true ->
<<1:1>>
end
end,
align,
begin
%% attribute id(1) with type OCTET STRING
Enc2@element = element(2, Val),
Enc3@len = byte_size(Enc2@element),
if Enc3@len < 128 ->
[Enc3@len|Enc2@element];
Enc3@len < 16384 ->
[<<2:2,Enc3@len:14>>|Enc2@element];
true ->
encode_fragmented(Enc2@element, 8)
end
end,
begin
%% attribute from(2) with type From
Enc4@element = element(3, Val),
enc_From(Enc4@element)
end,
align,
begin
%% attribute topic(3) with type OCTET STRING
Enc5@element = element(4, Val),
Enc6@len = byte_size(Enc5@element),
if Enc6@len < 128 ->
[Enc6@len|Enc5@element];
Enc6@len < 16384 ->
[<<2:2,Enc6@len:14>>|Enc5@element];
true ->
encode_fragmented(Enc5@element, 8)
end
end,
begin
%% attribute payload(4) with type OCTET STRING
Enc7@element = element(5, Val),
Enc8@len = byte_size(Enc7@element),
if Enc8@len < 128 ->
[Enc8@len|Enc7@element];
Enc8@len < 16384 ->
[<<2:2,Enc8@len:14>>|Enc7@element];
true ->
encode_fragmented(Enc7@element, 8)
end
end,
begin
%% attribute timestamp(5) with type INTEGER
Enc9@element = element(6, Val),
encode_unconstrained_number(Enc9@element)
end,
begin
%% attribute qos(6) with type INTEGER
Enc11@element = element(7, Val),
if 0 =< Enc11@element, Enc11@element < 3 ->
<<Enc11@element:2>>;
true ->
exit({error,{asn1,{illegal_integer,Enc11@element}}})
end
end,
begin
%% attribute sys(7) with type BOOLEAN
Enc13@element = element(8, Val),
%% attribute dup(8) with type BOOLEAN
Enc15@element = element(9, Val),
if Enc13@element =:= false ->
if Enc15@element =:= false ->
<<0:1,0:1>>;
Enc15@element =:= true ->
<<0:1,1:1>>;
true ->
exit({error,{asn1,{illegal_boolean,Enc15@element}}})
end;
Enc13@element =:= true ->
if Enc15@element =:= false ->
<<1:1,0:1>>;
Enc15@element =:= true ->
<<1:1,1:1>>;
true ->
exit({error,{asn1,{illegal_boolean,Enc15@element}}})
end;
true ->
exit({error,{asn1,{illegal_boolean,Enc13@element}}})
end
end,
begin
%% attribute retain(9) with type BOOLEAN
Enc17@element = element(10, Val),
if Enc17@element =:= false ->
<<0:1>>;
Enc17@element =:= true ->
<<1:1>>;
true ->
exit({error,{asn1,{illegal_boolean,Enc17@element}}})
end
end,
begin
%% attribute headers(10) with type StdHeaders
Enc19@element = element(11, Val),
enc_StdHeaders(Enc19@element)
end,
begin
%% attribute properties(11) with type StdProperties
Enc20@element = element(12, Val),
enc_StdProperties(Enc20@element)
end|begin
%% attribute misc(12) with type SEQUENCE OF
Enc21@element = element(13, Val),
if Enc21@element =:= asn1_NOVALUE ->
[];
true ->
enc_DurableMessage_misc(Enc21@element)
end
end].
enc_DurableMessage_misc(Val) ->
Enc1@len = length(Val),
if Enc1@len < 128 ->
[align,
Enc1@len|[enc_Misc(Comp) || Comp <- Val]];
Enc1@len < 16384 ->
[align,
<<2:2,Enc1@len:14>>|[enc_Misc(Comp) || Comp <- Val]];
true ->
begin
Enc1@fn = fun(Comp) -> enc_Misc(Comp) end,
encode_fragmented_sof(Enc1@fn, Val, Enc1@len)
end
end.



dec_DurableMessage(Bytes) ->
{Opt,Bytes1} = begin
<<V1@V0:1,V1@Buf1/bitstring>> = Bytes,
{V1@V0,V1@Buf1}
end,

%% attribute id(1) with type OCTET STRING
{Term1,Bytes2} = begin
V2@Pad3 = bit_size(Bytes1) band 7,
{V2@V0,V2@Buf1} = case Bytes1 of
<<_:V2@Pad3,0:1,V2@V5:7,V2@V7:V2@V5/binary-unit:8,V2@Buf8/bitstring>> ->
{V2@V7,V2@Buf8};
<<_:V2@Pad3,1:1,0:1,V2@V6:14,V2@V8:V2@V6/binary-unit:8,V2@Buf9/bitstring>> ->
{V2@V8,V2@Buf9};
<<_:V2@Pad3,1:1,1:1,V2@V6:6,V2@Buf7/bitstring>> ->
{V2@V8,V2@Buf9}  = decode_fragmented(V2@V6, V2@Buf7, 8),
{V2@V8,V2@Buf9}
end,
V2@Conv10 = binary:copy(V2@V0),
{V2@Conv10,V2@Buf1}
end,

%% attribute from(2) with type From
{Term2,Bytes3} = dec_From(Bytes2),

%% attribute topic(3) with type OCTET STRING
{Term3,Bytes4} = begin
V3@Pad3 = bit_size(Bytes3) band 7,
{V3@V0,V3@Buf1} = case Bytes3 of
<<_:V3@Pad3,0:1,V3@V5:7,V3@V7:V3@V5/binary-unit:8,V3@Buf8/bitstring>> ->
{V3@V7,V3@Buf8};
<<_:V3@Pad3,1:1,0:1,V3@V6:14,V3@V8:V3@V6/binary-unit:8,V3@Buf9/bitstring>> ->
{V3@V8,V3@Buf9};
<<_:V3@Pad3,1:1,1:1,V3@V6:6,V3@Buf7/bitstring>> ->
{V3@V8,V3@Buf9}  = decode_fragmented(V3@V6, V3@Buf7, 8),
{V3@V8,V3@Buf9}
end,
V3@Conv10 = binary:copy(V3@V0),
{V3@Conv10,V3@Buf1}
end,

%% attribute payload(4) with type OCTET STRING
{Term4,Bytes5} = begin
{V4@V0,V4@Buf1} = case Bytes4 of
<<0:1,V4@V3:7,V4@V5:V4@V3/binary-unit:8,V4@Buf6/bitstring>> ->
{V4@V5,V4@Buf6};
<<1:1,0:1,V4@V4:14,V4@V6:V4@V4/binary-unit:8,V4@Buf7/bitstring>> ->
{V4@V6,V4@Buf7};
<<1:1,1:1,V4@V4:6,V4@Buf5/bitstring>> ->
{V4@V6,V4@Buf7}  = decode_fragmented(V4@V4, V4@Buf5, 8),
{V4@V6,V4@Buf7}
end,
V4@Conv8 = binary:copy(V4@V0),
{V4@Conv8,V4@Buf1}
end,

%% attribute timestamp(5) with type INTEGER
{Term5,Bytes6} = begin
{V5@V0,V5@Buf1} = case Bytes5 of
<<0:1,V5@V3:7,V5@Buf4/bitstring>> when V5@V3 =/= 0 ->
{V5@V3,V5@Buf4};
<<1:1,0:1,V5@V4:14,V5@Buf5/bitstring>> when V5@V4 =/= 0 ->
{V5@V4,V5@Buf5};
<<1:1,1:1,V5@V4:6,V5@Buf5/bitstring>> when V5@V4 =/= 0 ->
V5@Mul6 = V5@V4 * 16384,
{V5@Mul6,V5@Buf5}
end,
<<V5@V7:V5@V0/signed-unit:8,V5@Buf8/bitstring>> = V5@Buf1,
{V5@V7,V5@Buf8}
end,

%% attribute qos(6) with type INTEGER
{Term6,Bytes7} = begin
<<V6@V0:2/unsigned-unit:1,V6@Buf1/bitstring>> = Bytes6,
{V6@V0,V6@Buf1}
end,

%% attribute sys(7) with type BOOLEAN
{Term7,Bytes8} = begin
<<V7@V0:1,V7@Buf1/bitstring>> = Bytes7,
V7@Int2 = case V7@V0 of
0 -> false;
1 -> true
end,
{V7@Int2,V7@Buf1}
end,

%% attribute dup(8) with type BOOLEAN
{Term8,Bytes9} = begin
<<V8@V0:1,V8@Buf1/bitstring>> = Bytes8,
V8@Int2 = case V8@V0 of
0 -> false;
1 -> true
end,
{V8@Int2,V8@Buf1}
end,

%% attribute retain(9) with type BOOLEAN
{Term9,Bytes10} = begin
<<V9@V0:1,V9@Buf1/bitstring>> = Bytes9,
V9@Int2 = case V9@V0 of
0 -> false;
1 -> true
end,
{V9@Int2,V9@Buf1}
end,

%% attribute headers(10) with type StdHeaders
{Term10,Bytes11} = dec_StdHeaders(Bytes10),

%% attribute properties(11) with type StdProperties
{Term11,Bytes12} = dec_StdProperties(Bytes11),

%% attribute misc(12) with type SEQUENCE OF
{Term12,Bytes13} = case Opt band 1 of
1 ->
dec_DurableMessage_misc(Bytes12);
0 ->
{asn1_NOVALUE,Bytes12}
end,
Res1 = {'DurableMessage',Term1,Term2,Term3,Term4,Term5,Term6,Term7,Term8,Term9,Term10,Term11,Term12},
{Res1,Bytes13}.


dec_DurableMessage_misc(Bytes) ->
dec_components2(Bytes, []).


%%%
%%% Run-time functions.
%%%

'dialyzer-suppressions'(Arg) ->
    _ = complete(element(1, Arg)),
    ok.

dec_components1(Bytes, Acc) ->
%% Length with constraint no
V1@Pad3 = bit_size(Bytes) band 7,
{V1@V0,V1@Buf1} = case Bytes of
<<_:V1@Pad3,0:1,V1@V5:7,V1@Buf6/bitstring>> ->
{V1@V5,V1@Buf6};
<<_:V1@Pad3,1:1,0:1,V1@V6:14,V1@Buf7/bitstring>> ->
{V1@V6,V1@Buf7};
<<_:V1@Pad3,1:1,1:1,V1@V6:6,V1@Buf7/bitstring>> ->
V1@Mul8 = V1@V6 * 16384,
{V1@Mul8,V1@Buf7}
end,
{Acc1,Buf1} = dec_fragment3(V1@V0, V1@Buf1, Acc),
if V1@V0 >= 16384 ->
dec_components1(Buf1, Acc1);
true ->
{lists:reverse(Acc1),Buf1}
end.

dec_components2(Bytes, Acc) ->
%% Length with constraint no
V2@Pad3 = bit_size(Bytes) band 7,
{V2@V0,V2@Buf1} = case Bytes of
<<_:V2@Pad3,0:1,V2@V5:7,V2@Buf6/bitstring>> ->
{V2@V5,V2@Buf6};
<<_:V2@Pad3,1:1,0:1,V2@V6:14,V2@Buf7/bitstring>> ->
{V2@V6,V2@Buf7};
<<_:V2@Pad3,1:1,1:1,V2@V6:6,V2@Buf7/bitstring>> ->
V2@Mul8 = V2@V6 * 16384,
{V2@Mul8,V2@Buf7}
end,
{Acc1,Buf1} = dec_fragment4(V2@V0, V2@Buf1, Acc),
if V2@V0 >= 16384 ->
dec_components2(Buf1, Acc1);
true ->
{lists:reverse(Acc1),Buf1}
end.

dec_fragment3(0, Bytes, Acc) ->
{Acc,Bytes};
dec_fragment3(Num, Bytes, Acc) ->
{Term,Remain} = dec_UserProperty(Bytes),
dec_fragment3(Num-1, Remain, [Term|Acc]).

dec_fragment4(0, Bytes, Acc) ->
{Acc,Bytes};
dec_fragment4(Num, Bytes, Acc) ->
{Term,Remain} = dec_Misc(Bytes),
dec_fragment4(Num-1, Remain, [Term|Acc]).

complete(L0) ->
    L = complete(L0, []),
    case list_to_bitstring(L) of
        <<>> ->
            <<0>>;
        Bin ->
            Bin
    end.

complete([], Bits, []) ->
    case Bits band 7 of
        0 ->
            [];
        N ->
            [<<0:(8 - N)>>]
    end;
complete([], Bits, [H | More]) ->
    complete(H, Bits, More);
complete([align | T], Bits, More) ->
    case Bits band 7 of
        0 ->
            complete(T, More);
        1 ->
            [<<0:7>> | complete(T, More)];
        2 ->
            [<<0:6>> | complete(T, More)];
        3 ->
            [<<0:5>> | complete(T, More)];
        4 ->
            [<<0:4>> | complete(T, More)];
        5 ->
            [<<0:3>> | complete(T, More)];
        6 ->
            [<<0:2>> | complete(T, More)];
        7 ->
            [<<0:1>> | complete(T, More)]
    end;
complete([[] | T], Bits, More) ->
    complete(T, Bits, More);
complete([[_ | _] = H], Bits, More) ->
    complete(H, Bits, More);
complete([[_ | _] = H | T], Bits, More) ->
    complete(H, Bits, [T | More]);
complete([H | T], Bits, More) when is_integer(H); is_binary(H) ->
    [H | complete(T, Bits, More)];
complete([H | T], Bits, More) ->
    [H | complete(T, Bits + bit_size(H), More)];
complete(Bin, Bits, More) when is_binary(Bin) ->
    [Bin | complete([], Bits, More)];
complete(Bin, Bits, More) ->
    [Bin | complete([], Bits + bit_size(Bin), More)].

complete([], []) ->
    [];
complete([], [H | More]) ->
    complete(H, More);
complete([align | T], More) ->
    complete(T, More);
complete([[] | T], More) ->
    complete(T, More);
complete([[_ | _] = H], More) ->
    complete(H, More);
complete([[_ | _] = H | T], More) ->
    complete(H, [T | More]);
complete([H | T], More) when is_integer(H); is_binary(H) ->
    [H | complete(T, More)];
complete([H | T], More) ->
    [H | complete(T, bit_size(H), More)];
complete(Bin, More) when is_binary(Bin) ->
    [Bin | complete([], More)];
complete(Bin, More) ->
    [Bin | complete([], bit_size(Bin), More)].

decode_fragmented(SegSz0, Buf0, Unit) ->
    SegSz = SegSz0 * Unit * 16384,
    <<Res:SegSz/bitstring,Buf/bitstring>> = Buf0,
    decode_fragmented_1(Buf, Unit, Res).

decode_fragmented_1(<<0:1,N:7,Buf0/bitstring>>, Unit, Res) ->
    Sz = N * Unit,
    <<S:Sz/bitstring,Buf/bitstring>> = Buf0,
    {<<Res/bitstring,S/bitstring>>, Buf};
decode_fragmented_1(<<1:1,0:1,N:14,Buf0/bitstring>>, Unit, Res) ->
    Sz = N * Unit,
    <<S:Sz/bitstring,Buf/bitstring>> = Buf0,
    {<<Res/bitstring,S/bitstring>>, Buf};
decode_fragmented_1(<<1:1,1:1,SegSz0:6,Buf0/bitstring>>, Unit, Res0) ->
    SegSz = SegSz0 * Unit * 16384,
    <<Frag:SegSz/bitstring,Buf/bitstring>> = Buf0,
    Res = <<Res0/bitstring,Frag/bitstring>>,
    decode_fragmented_1(Buf, Unit, Res).

encode_components(Cs, _Encoder, 0, Acc) ->
    {Cs, lists:reverse(Acc)};
encode_components([C | Cs], Encoder, Size, Acc) ->
    B = Encoder(C),
    encode_components(Cs, Encoder, Size - 1, [B | Acc]).

encode_fragmented(Bin, Unit) ->
    encode_fragmented_1(Bin, Unit, 4).

encode_fragmented_1(Bin, Unit, N) ->
    SegSz = Unit * N * 16384,
    case Bin of
        <<B:SegSz/bitstring,T/bitstring>> ->
            [<<3:2,N:6>>, B | encode_fragmented_1(T, Unit, N)];
        _ when N > 1 ->
            encode_fragmented_1(Bin, Unit, N - 1);
        _ ->
            case bit_size(Bin) div Unit of
                Len when Len < 128 ->
                    [Len, Bin];
                Len when Len < 16384 ->
                    [<<2:2,Len:14>>, Bin]
            end
    end.

encode_fragmented_sof(Fun, Comps, Len) ->
    encode_fragmented_sof_1(Fun, Comps, Len, 4).

encode_fragmented_sof_1(Encoder, Comps0, Len0, N) ->
    SegSz = N * 16384,
    if
        Len0 >= SegSz ->
            {Comps, B} = encode_components(Comps0, Encoder, SegSz, []),
            Len = Len0 - SegSz,
            [align,
             <<3:2,N:6>>,
             B |
             encode_fragmented_sof_1(Encoder, Comps, Len, N)];
        N > 1 ->
            encode_fragmented_sof_1(Encoder, Comps0, Len0, N - 1);
        Len0 < 128 ->
            {[], B} = encode_components(Comps0, Encoder, Len0, []),
            [align, Len0 | B];
        Len0 < 16384 ->
            {[], B} = encode_components(Comps0, Encoder, Len0, []),
            [align, <<2:2,Len0:14>> | B]
    end.

encode_unconstrained_number(Val) when not is_integer(Val) ->
    exit({error, {asn1, {illegal_integer, Val}}});
encode_unconstrained_number(Val) when Val >= 0 ->
    if
        Val < 128 ->
            [1, Val];
        Val < 256 ->
            [<<2,0>>, Val];
        true ->
            case binary:encode_unsigned(Val) of
                <<0:1,_/bitstring>> = Bin ->
                    case byte_size(Bin) of
                        Sz when Sz < 128 ->
                            [Sz, Bin];
                        Sz when Sz < 16384 ->
                            [<<2:2,Sz:14>>, Bin]
                    end;
                <<1:1,_/bitstring>> = Bin ->
                    case byte_size(Bin) + 1 of
                        Sz when Sz < 128 ->
                            [Sz, 0, Bin];
                        Sz when Sz < 16384 ->
                            [<<2:2,Sz:14,0:8>>, Bin]
                    end
            end
    end;
encode_unconstrained_number(Val) ->
    Oct = enint(Val, []),
    Len = length(Oct),
    if
        Len < 128 ->
            [Len | Oct];
        Len < 16384 ->
            [<<2:2,Len:14>> | Oct]
    end.

enint(-1, [B1 | T]) when B1 > 127 ->
    [B1 | T];
enint(N, Acc) ->
    enint(N bsr 8, [N band 255 | Acc]).
